/**
 * Tests the standard evaluator's bind join into {@code GRAPH}: physical effect (which lookups happen), plan shape (join
 * algorithm and order) and the bodies that must keep the independent hash join.
 */
public class GraphBindJoinTest {

	private static final SimpleValueFactory VF = SimpleValueFactory.getInstance();
	private static final String NS = "http://example.com/";
	private static final String PREFIX = "PREFIX : <" + NS + "> PREFIX rdf: <" + RDF.NAMESPACE + "> ";
	private static final IRI P = iri("p");
	private static final IRI O = iri("o");
	private static final IRI T1 = iri("T1");
	private static final IRI T2 = iri("T2");
	private static final IRI G1 = iri("g1");
	private static final IRI G2 = iri("g2");
	private static final IRI G3 = iri("g3");

	private static IRI iri(String local) {
		return VF.createIRI(NS + local);
	}

	private record Call(Resource subject, IRI predicate, Value object, List<Resource> contexts) {
	}

	/** A small quad store that records every lookup. */
	private static final class RecordingSource implements TripleSource {
		private final List<Statement> data = new ArrayList<>();
		private final List<Resource> contexts = new ArrayList<>();
		private final List<Call> calls = new ArrayList<>();
		private int contextScans;

		private RecordingSource(boolean physicalNil) {
			add(iri("x1"), RDF.TYPE, T1, G1);
			add(iri("x2"), RDF.TYPE, T2, G1);
			add(iri("x1"), P, O, G1);
			add(iri("x1"), RDF.TYPE, iri("T3"), G2);
			add(iri("y"), RDF.TYPE, T1, G2);
			add(iri("z"), RDF.TYPE, T1, G3);
			add(iri("d"), P, O, null);
			if (physicalNil) {
				add(iri("nilSubject"), P, iri("nilObject"), RDF4J.NIL);
			}
		}

		private void add(Resource s, IRI p, Value o, Resource c) {
			data.add(c == null ? VF.createStatement(s, p, o) : VF.createStatement(s, p, o, c));
			if (c != null && !contexts.contains(c)) {
				contexts.add(c);
			}
		}

		@Override
		public CloseableIteration<? extends Resource> getContextIDs() {
			contextScans++;
			return new CloseableIteratorIteration<>(List.copyOf(contexts).iterator());
		}

		@Override
		public CloseableIteration<? extends Statement> getStatements(Resource subject, IRI predicate, Value object,
				Resource... contexts) {
			calls.add(new Call(subject, predicate, object, List.of(contexts)));
			Iterator<Statement> matching = data.stream()
					.filter(st -> (subject == null || subject.equals(st.getSubject()))
							&& (predicate == null || predicate.equals(st.getPredicate()))
							&& (object == null || object.equals(st.getObject()))
							&& (contexts.length == 0 || Arrays.asList(contexts).contains(st.getContext())))
					.toList()
					.iterator();
			return new CloseableIteratorIteration<>(matching);
		}

		@Override
		public SimpleValueFactory getValueFactory() {
			return VF;
		}
	}

	private static final class Run {
		private final RecordingSource source;
		private final TupleExpr plan;
		private final List<BindingSet> rows;

		private Run(boolean physicalNil, String query) {
			this(physicalNil, query, false);
		}

		private Run(boolean physicalNil, String query, boolean telemetry) {
			source = new RecordingSource(physicalNil);
			DefaultEvaluationStrategy strategy = new DefaultEvaluationStrategy(source, null);
			strategy.setTrackResultSize(telemetry);
			strategy.setTrackTime(telemetry);
			plan = new QueryRoot(QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL, PREFIX + query, null)
					.getTupleExpr());
			strategy.optimize(plan, new EvaluationStatistics(), EmptyBindingSet.getInstance());
			rows = new ArrayList<>();
			try (CloseableIteration<BindingSet> result = strategy.precompile(plan)
					.evaluate(EmptyBindingSet.getInstance())) {
				while (result.hasNext()) {
					rows.add(result.next());
				}
			}
		}

		private Run(String query) {
			this(false, query);
		}

		private List<String> bag(String... names) {
			return rows.stream().map(row -> Arrays.stream(names).map(n -> {
				Value v = row.getValue(n);
				return v == null ? "-" : v.stringValue().replace(NS, "");
			}).collect(Collectors.joining(","))).sorted().toList();
		}

		private List<Join> joins() {
			List<Join> joins = new ArrayList<>();
			plan.visit(new AbstractQueryModelVisitor<RuntimeException>() {
				@Override
				public void meet(Join node) {
					joins.add(node);
					super.meet(node);
				}
			});
			return joins;
		}

		private List<Join> joinsWithGraph() {
			return joins().stream()
					.filter(j -> containsGraph(j.getLeftArg()) || containsGraph(j.getRightArg()))
					.toList();
		}

		private List<String> graphJoinAlgorithms() {
			return joinsWithGraph().stream().map(Join::getAlgorithmName).toList();
		}
	}

	private static boolean containsGraph(TupleExpr expr) {
		boolean[] found = { false };
		expr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Graph node) {
				found[0] = true;
			}
		});
		return found[0];
	}

	private static boolean unboundSubjectTypeLookup(Call call) {
		return call.subject() == null && RDF.TYPE.equals(call.predicate()) && call.object() == null;
	}

	@Test
	public void siblingStatementPatternBindsSubjectBeforeGraphLookup() {
		Run run = new Run("SELECT ?a ?g ?t { ?a :p :o . GRAPH ?g { ?a a ?t } }");
		assertThat(run.bag("a", "g", "t")).containsExactly("x1,g1,T1", "x1,g2,T3");
		assertThat(run.source.calls).noneMatch(GraphBindJoinTest::unboundSubjectTypeLookup);
		assertThat(run.graphJoinAlgorithms()).containsExactly("GraphBindJoinIteration");
	}

	@Test
	public void siblingValuesBindSubjectBeforeGraphLookup() {
		Run run = new Run("SELECT ?a ?g ?t { VALUES ?a { :x1 :x2 } GRAPH ?g { ?a a ?t } }");
		assertThat(run.bag("a", "g", "t")).containsExactly("x1,g1,T1", "x1,g2,T3", "x2,g1,T2");
		assertThat(run.source.calls).noneMatch(GraphBindJoinTest::unboundSubjectTypeLookup);
		assertThat(run.graphJoinAlgorithms()).containsExactly("GraphBindJoinIteration");
	}

	@Test
	public void telemetryKeepsTheBindJoinAndCountsGraphRows() {
		Run run = new Run(false, "SELECT ?a ?g ?t { VALUES ?a { :x1 :x2 } GRAPH ?g { ?a a ?t } }", true);
		assertThat(run.bag("a", "g", "t")).containsExactly("x1,g1,T1", "x1,g2,T3", "x2,g1,T2");
		assertThat(run.graphJoinAlgorithms()).containsExactly("GraphBindJoinIteration");
		Graph graph = graphOf(run.plan);
		assertThat(graph.getResultSizeActual()).isEqualTo(3);
		assertThat(run.source.calls).noneMatch(GraphBindJoinTest::unboundSubjectTypeLookup);
	}

	@Test
	public void noSharedVariableKeepsTheIndependentGraphAndTheOldOrder() {
		Run run = new Run("SELECT * { ?s :p ?o . GRAPH ?g { ?x a :T1 } }");
		assertThat(run.graphJoinAlgorithms()).isNotEmpty().doesNotContain("GraphBindJoinIteration");
		// the graph stays a priority argument, evaluated before the statement pattern
		assertThat(run.joinsWithGraph()).noneMatch(join -> join.getRightArg() instanceof Graph);
		assertThat(run.bag("s", "g", "x")).containsExactly("d,g1,x1", "d,g2,y", "d,g3,z", "x1,g1,x1", "x1,g2,y",
				"x1,g3,z");
	}

	@Test
	public void enumeratingBindJoinIsOnlyUsedForSmallLeftOperands() {
		StringBuilder large = new StringBuilder();
		for (int i = 0; i < 600; i++) {
			large.append(":l").append(i).append(' ');
		}
		Run big = new Run("SELECT * { VALUES ?a { " + large + "} GRAPH ?g { ?a a ?t } }");
		assertThat(big.graphJoinAlgorithms()).isNotEmpty().doesNotContain("GraphBindJoinIteration");
		Run small = new Run("SELECT * { VALUES ?a { :x1 :x2 } GRAPH ?g { ?a a ?t } }");
		assertThat(small.graphJoinAlgorithms()).containsExactly("GraphBindJoinIteration");
		// a selector bound by the left operand needs no budget: each row evaluates one graph
		Run selected = new Run("SELECT * { VALUES ?g { :g1 :g2 } VALUES ?a { " + large + "} GRAPH ?g { ?a a ?t } }");
		assertThat(selected.graphJoinAlgorithms()).contains("GraphBindJoinIteration");
	}

	@Test
	public void enumerationDomainIsLoadedOnceForSeveralLeftRows() {
		Run run = new Run("SELECT ?g ?s { VALUES ?g { :g1 :g2 :g3 :g1 } GRAPH ?g { ?s :p ?o } }");
		assertThat(run.graphJoinAlgorithms()).containsExactly("GraphBindJoinIteration");
		assertThat(run.bag("g", "s")).containsExactly("g1,x1", "g1,x1");
		assertThat(run.source.contextScans).isEqualTo(1);
	}

	@Test
	public void siblingValuesSelectOneGraphOnly() {
		Run run = new Run("SELECT ?g ?s ?o { VALUES ?g { :g1 } GRAPH ?g { ?s ?p ?o } }");
		assertThat(run.bag("g", "s", "o")).containsExactly("g1,x1,T1", "g1,x1,o", "g1,x2,T2");
		assertThat(run.source.calls).isNotEmpty()
				.allSatisfy(call -> assertThat(call.contexts()).containsExactly(G1));
		assertThat(run.graphJoinAlgorithms()).containsExactly("GraphBindJoinIteration");
	}

	@Test
	public void siblingValuesNonMemberSelectNothingAndReadNoGraph() {
		Run run = new Run("SELECT ?g ?s { VALUES ?g { :unknown 1 } GRAPH ?g { ?s ?p ?o } }");
		assertThat(run.rows).isEmpty();
		assertThat(run.source.calls).isEmpty();
	}

	@Test
	public void siblingBoundDefaultAliasIsNotTheDefaultGraph() {
		// no physical context named rdf4j:nil: the alias is not in the enumeration domain, so no rows
		Run absent = new Run(false, "SELECT ?g ?s { VALUES ?g { <" + RDF4J.NIL + "> } GRAPH ?g { ?s :p ?o } }");
		assertThat(absent.rows).isEmpty();
		assertThat(absent.source.calls).isEmpty();

		// a physical context with that name is read as that physical context, never the default graph
		Run present = new Run(true, "SELECT ?g ?s ?o { VALUES ?g { <" + RDF4J.NIL + "> } GRAPH ?g { ?s :p ?o } }");
		assertThat(present.bag("g", "s", "o")).containsExactly(RDF4J.NIL.stringValue() + ",nilSubject,nilObject");
		assertThat(present.source.calls).allSatisfy(call -> assertThat(call.contexts()).containsExactly(RDF4J.NIL));
	}

	@Test
	public void targetQueryOrdersValuesBeforeGraphAndBindJoins() {
		Run run = new Run("SELECT ?a ?g ?b ?c ?d { "
				+ "VALUES ?a { :x1 :x2 :x3 } VALUES ?g { :g1 :g2 } "
				+ "GRAPH ?g { ?b a :T1 . ?a a ?t . OPTIONAL { ?a :p ?c } OPTIONAL { ?b :p2 ?d } } }");
		List<Join> joins = run.joinsWithGraph();
		assertThat(run.graphJoinAlgorithms()).contains("GraphBindJoinIteration");
		Join graphJoin = joins.stream().filter(j -> j.getRightArg() instanceof Graph).findFirst().orElseThrow();
		assertThat(graphJoin.getLeftArg().getBindingNames()).contains("a", "g");
		assertThat(containsGraph(graphJoin.getLeftArg())).isFalse();
		assertThat(run.bag("a", "g", "b", "c")).containsExactly("x1,g1,x1,o", "x1,g2,y,-", "x2,g1,x1,-");
		assertThat(run.source.calls).noneMatch(GraphBindJoinTest::unboundSubjectTypeLookup);
	}

	static Stream<String> rejectedBodies() {
		return Stream.of(
				"SELECT * { VALUES ?a { :x1 } GRAPH ?g { ?a a ?t . BIND(UUID() AS ?u) } }",
				"SELECT * { VALUES ?a { :x1 } GRAPH ?g { ?a a ?t . BIND(BNODE() AS ?u) } }",
				"SELECT * { VALUES ?a { :x1 } GRAPH ?g { SERVICE <http://example.com/sparql> { ?a a ?t } } }",
				"SELECT * { VALUES ?a { :x1 } GRAPH ?g { ?a a ?t MINUS { ?a :p ?z } } }",
				"SELECT * { VALUES ?k { 1 } GRAPH ?g { ?a a ?t FILTER(!BOUND(?k)) } }",
				"SELECT * { VALUES ?a { :x1 } GRAPH ?g { GRAPH ?h { ?a a ?t } } }");
	}

	@ParameterizedTest
	@ValueSource(ints = { 0, 1, 2, 3, 4, 5 })
	public void rejectedBodiesAreNotBindJoined(int index) {
		String query = rejectedBodies().toList().get(index);
		Run run;
		try {
			run = new Run(query);
		} catch (RuntimeException e) {
			// SERVICE needs a resolver to execute; the join algorithm is chosen when the plan is prepared
			assertThat(query).contains("SERVICE");
			return;
		}
		assertThat(run.graphJoinAlgorithms()).as(query).isNotEmpty().doesNotContain("GraphBindJoinIteration");
		// the graph is never the bind-joined right operand: it keeps its independent evaluation
		assertThat(run.joinsWithGraph()).as(query)
				.noneMatch(join -> join.getRightArg() instanceof Graph
						&& !"HashJoinIteration".equals(join.getAlgorithmName()));
	}

	@Test
	public void permitsGraphBindJoinDecidesPerGraph() {
		TupleExpr ok = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT * { GRAPH ?g { ?a <http://example.com/p> ?b } }", null).getTupleExpr();
		Graph okGraph = graphOf(ok);
		assertThat(QueryEvaluationUtility.permitsGraphBindJoin(okGraph, Set.of("a", "g"))).isTrue();
		TupleExpr volatileBody = QueryParserUtil.parseTupleQuery(QueryLanguage.SPARQL,
				"SELECT * { GRAPH ?g { ?a <http://example.com/p> ?b BIND(UUID() AS ?u) } }", null).getTupleExpr();
		assertThat(QueryEvaluationUtility.permitsGraphBindJoin(graphOf(volatileBody), Set.of("a"))).isFalse();
	}

	private static Graph graphOf(TupleExpr expr) {
		List<Graph> graphs = new ArrayList<>();
		expr.visit(new AbstractQueryModelVisitor<RuntimeException>() {
			@Override
			public void meet(Graph node) {
				graphs.add(node);
			}
		});
		return graphs.get(0);
	}
}
